options.customCss:
:root {
  --font-family: 'Inter', -apple-system, 'Segoe UI', Helvetica, Arial, sans-serif;
  --color-background: #EEF2FF;
  --color-card-bg: #FFFFFF;
  --color-card-border: #E0E7FF;
  --color-card-shadow: rgba(67, 56, 202, 0.12);
  --color-header: #111827;
  --color-label: #374151;
  --color-input-border: #D1D5DB;
  --color-input-text: #111827;
  --color-focus-border: #6366F1;
  --color-submit-btn-bg: #4F46E5;
  --color-submit-btn-text: #FFFFFF;
  --border-radius-card: 16px;
  --border-radius-input: 10px;
  --container-width: 560px;
  --font-size-header: 26px;
  --font-size-label: 14px;
  --font-size-input: 15px;
}

body {
  background: linear-gradient(160deg, #EEF2FF 0%, #F8FAFC 60%);
}

.card {
  padding: 40px 36px;
  box-shadow: 0 10px 40px var(--color-card-shadow);
}

.header::before {
  content: '';
  display: block;
  width: 64px;
  height: 64px;
  margin: 0 auto 18px;
  background: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 64 64%22 width=%2264%22 height=%2264%22%3E %3Cdefs%3E %3ClinearGradient id=%22g%22 x1=%220%22 y1=%220%22 x2=%221%22 y2=%221%22%3E %3Cstop offset=%220%22 stop-color=%22%236366F1%22/%3E %3Cstop offset=%221%22 stop-color=%22%234338CA%22/%3E %3C/linearGradient%3E %3C/defs%3E %3Crect width=%2264%22 height=%2264%22 rx=%2216%22 fill=%22url(%23g)%22/%3E %3Cpath d=%22M22 14h14l8 8v26a2 2 0 0 1-2 2H22a2 2 0 0 1-2-2V16a2 2 0 0 1 2-2z%22 fill=%22%23FFFFFF%22/%3E %3Cpath d=%22M36 14v6a2 2 0 0 0 2 2h6z%22 fill=%22%23C7D2FE%22/%3E %3Crect x=%2225%22 y=%2227%22 width=%2214%22 height=%222.5%22 rx=%221.25%22 fill=%22%23C7D2FE%22/%3E %3Crect x=%2225%22 y=%2232%22 width=%2210%22 height=%222.5%22 rx=%221.25%22 fill=%22%23C7D2FE%22/%3E %3Ccircle cx=%2244%22 cy=%2244%22 r=%229%22 fill=%22%2322C55E%22 stroke=%22%23FFFFFF%22 stroke-width=%222.5%22/%3E %3Cpath d=%22M40 44.2l2.8 2.8 5.2-5.6%22 fill=%22none%22 stroke=%22%23FFFFFF%22 stroke-width=%222.6%22 stroke-linecap=%22round%22 stroke-linejoin=%22round%22/%3E %3C/svg%3E") center / contain no-repeat;
}

.header h1 {
  font-weight: 700;
  letter-spacing: -0.02em;
}

.header p {
  color: #6B7280;
  line-height: 1.6;
}

.submit-btn {
  font-weight: 600;
  letter-spacing: 0.01em;
  transition: background 0.15s ease;
}

.submit-btn:hover {
  background: #4338CA;
}

